use uuid::Uuid;

/// A single execution of a script.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ScriptRun {
    /// Time-ordered (UUIDv7) id of this run.
    pub id: Uuid,
    /// The script this run executed.
    pub script_id: Uuid,
}

impl ScriptRun {
    /// Create a new run of `script_id` with a fresh UUIDv7 id, which sorts by creation time.
    #[must_use]
    pub fn new(script_id: Uuid) -> Self {
        Self {
            id: Uuid::now_v7(),
            script_id,
        }
    }
}
```

